// SCRATCH-HARNESS-BEGIN (not committed)
#[cfg(test)]
mod oracle_harness {
    use super::*;
    use crate::import_map::{ImportResolutionMap, ReExportStep};
    use crate::resolver::{ModuleResolution, ModuleResolvers, resolve_module_with};
    use crate::types::{GlobalSourceData, PipelineOptions, SourceData};
    use rayon::prelude::*;

    #[test]
    #[ignore = "scratch"]
    fn oracle_harness() {
        let root = Utf8PathBuf::from(std::env::var("CORPUS_ROOT").unwrap());
        let src = Utf8PathBuf::from(std::env::var("CORPUS_SRC").unwrap());
        let out = std::env::var("OUT").unwrap();
        let mut paths = Vec::new();
        let walker = ignore::WalkBuilder::new(&root)
            .standard_filters(false)
            .filter_entry(|e| !matches!(e.file_name().to_str(), Some("node_modules" | "dist" | "build" | ".git")))
            .build();
        for entry in walker.flatten() {
            let Ok(path) = Utf8PathBuf::from_path_buf(entry.into_path()) else { continue };
            let name = path.as_str();
            if [".ts", ".tsx", ".js", ".jsx", ".mts"].iter().any(|ext| name.ends_with(ext)) && !name.ends_with(".d.ts") && path.is_file() {
                paths.push(path);
            }
        }
        paths.sort();
        let data: Vec<SourceData> = paths
            .par_iter()
            .map(|path| {
                let source = std::fs::read_to_string(path).unwrap_or_default();
                let mut d = crate::extractor::parse_file(path, &source);
                d.file_path = path.clone();
                d
            })
            .collect();
        let mut global = GlobalSourceData::default();
        for d in &data {
            global.import_map.insert(d.file_path.clone(), d.imports.clone());
            global.re_export_map.insert(d.file_path.clone(), d.exports.clone());
        }
        let map = ImportResolutionMap::build(&global);
        let resolvers = ModuleResolvers::new(&PipelineOptions::default());
        let resolve = |spec: &str, from: &Utf8Path| match resolve_module_with(&resolvers.main, &resolvers.types_first, spec, from) {
            ModuleResolution::File(p) | ModuleResolution::PackageTypes(p) => Some(p),
            ModuleResolution::Unresolved(_) => None,
        };
        let declared: std::collections::HashSet<(Utf8PathBuf, String)> = data
            .iter()
            .flat_map(|d| d.component_mappings.iter().map(|c| (c.file_path.clone(), c.binding_name().to_owned())))
            .collect();
        fn follow(
            map: &ImportResolutionMap,
            resolve: &dyn Fn(&str, &Utf8Path) -> Option<Utf8PathBuf>,
            declared: &std::collections::HashSet<(Utf8PathBuf, String)>,
            file: Utf8PathBuf,
            name: String,
            depth: u8,
        ) -> Option<(Utf8PathBuf, String)> {
            if depth > 8 {
                return None;
            }
            if let Some(local) = map.local_export(&file, &name) {
                return Some((file, local));
            }
            if declared.contains(&(file.clone(), name.clone())) {
                return Some((file, name));
            }
            match map.resolve_reexport_chain(&file, &name)? {
                ReExportStep::Named { source_specifier, source_name } => {
                    let next = resolve(&source_specifier, &file)?;
                    follow(map, resolve, declared, next, source_name, depth + 1)
                }
                ReExportStep::Wildcards(specs) => specs.iter().find_map(|spec| {
                    let next = resolve(spec, &file)?;
                    follow(map, resolve, declared, next, name.clone(), depth + 1)
                }),
            }
        }
        let canonical = |file: &Utf8Path, name: &str| -> Option<(Utf8PathBuf, String)> {
            if let Some(r) = map.find_import(file, name) {
                let target = resolve(&r.specifier, file)?;
                return follow(&map, &resolve, &declared, target, r.exported_name.to_string(), 0);
            }
            let (ns, member) = name.split_once('.')?;
            let r = map.find_import(file, ns)?;
            let member = if r.exported_name == "*" || r.exported_name == "default" { member.to_owned() } else { format!("{}.{member}", r.exported_name) };
            let target = resolve(&r.specifier, file)?;
            follow(&map, &resolve, &declared, target, member, 0)
        };
        let components: Vec<ComponentMapping> = data.iter().flat_map(|d| d.component_mappings.iter().cloned()).collect();
        let jsx_files: Vec<FileUsages<'_>> = data
            .iter()
            .filter(|d| d.file_path.as_str().ends_with(".tsx") || d.file_path.as_str().ends_with(".jsx"))
            .map(|d| FileUsages { file: &d.file_path, usages: &d.jsx_usages })
            .collect();
        // Body elements are only counted for .tsx/.jsx, as the oracle walks those.
        let components_counted: Vec<ComponentMapping> = components
            .iter()
            .cloned()
            .map(|mut c| {
                if !(c.file_path.as_str().ends_with(".tsx") || c.file_path.as_str().ends_with(".jsx")) {
                    c.body = None;
                }
                c
            })
            .collect();
        let counted = count(&components_counted, &jsx_files, canonical);
        let mut rows = Vec::new();
        for (c, sites) in components.iter().zip(&counted) {
            if !c.file_path.starts_with(&src) {
                continue;
            }
            let exports: Vec<String> = c.exports.iter().map(ToString::to_string).collect();
            rows.push(serde_json::json!({
                "file": c.file_path, "binding": c.binding_name(), "exports": exports,
                "sites": sites.sites, "used": sites.used(), "passed": sites.passed,
            }));
        }
        std::fs::write(out, serde_json::to_string(&rows).unwrap()).unwrap();
    }
}
