#!/usr/bin/env python3
"""Scratch (not committed): T6 'used' sets vs the TypeScript call-site oracle (relevance/out/<name>.sites.json).

Usage: compare.py <harness name> <oracle name>. Floor on both sides: >= 3 sites, used = count >= 2 and 5*count >= sites.
`key` is dropped on both sides (the oracle drops it)."""
import collections
import json
import sys

H = '/Users/gabe/Projects/caliper-fixtures/shrink/call-sites-check'
O = '/Users/gabe/Projects/caliper-fixtures/shrink/relevance/out'
mine_name, oracle_name = sys.argv[1], sys.argv[2]
rows = json.load(open(f'{H}/{mine_name}.json'))
sites = json.load(open(f'{O}/{oracle_name}.sites.json'))['sites']

ident = {}
for i, r in enumerate(rows):
    for e in r['exports']:
        if '.' not in e:
            ident.setdefault((r['file'], e), i)

by = collections.defaultdict(list)
for s in sites:
    k = next((ident[(f, n)] for f, n in s['chain'] if (f, n) in ident), None)
    if k is not None:
        by[k].append(s)


def used_of(n, counts):
    return {a for a, c in counts.items() if a != 'key' and c >= 2 and 5 * c >= n}


oracle = {}
for k, ss in by.items():
    if len(ss) < 3:
        continue
    cnt = collections.Counter(a for s in ss for a in set(s['attrs']))
    oracle[k] = (len(ss), used_of(len(ss), cnt))
mine = {}
for i, r in enumerate(rows):
    if r['sites'] >= 3:
        mine[i] = (r['sites'], {a for a in r['used'] if a != 'key'})

both = set(oracle) & set(mine)
tp = sum(len(mine[k][1] & oracle[k][1]) for k in both)
mp = sum(len(v[1]) for v in mine.values())
op = sum(len(v[1]) for v in oracle.values())
tp_all = tp
p = tp_all / mp if mp else float('nan')
rc = tp_all / op if op else float('nan')
pb = tp / sum(len(mine[k][1]) for k in both) if both else float('nan')
rb = tp / sum(len(oracle[k][1]) for k in both) if both else float('nan')
exact = sum(1 for k in both if mine[k][1] == oracle[k][1])
print(f'{mine_name}: components with evidence mine={len(mine)} oracle={len(oracle)} both={len(both)} '
      f'| used pairs mine={mp} oracle={op} agree={tp} | precision={p:.3f} recall={rc:.3f} '
      f'| on shared components precision={pb:.3f} recall={rb:.3f} identical sets={exact}/{len(both)}')
if '-v' in sys.argv:
    for k in sorted(set(oracle) | set(mine), key=lambda k: rows[k]['file']):
        m, o = mine.get(k, (0, set())), oracle.get(k, (0, set()))
        if m[1] != o[1]:
