    fn tag(&mut self, file: &Utf8Path, tag: &JsxTag) -> Option<usize> {
        match tag {
            JsxTag::Intrinsic(_) => None,
            JsxTag::Identifier(path) | JsxTag::Member(path) => self.path(file, path),
        }
    }

